messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 10px;
            width: 100%;
            text-align: center;
            color: #ffffff;
            font-family: sans-serif;
            font-size: 14px;
            pointer-events: none;
            opacity: 0.7;
        }
    </style>
</head>
<body>
    <div id="info">Cycle: Stand (2s) -> Walk (3s) -> Run (3s) -> Stand (2s)</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- SCENE SETUP ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);

        // Camera: Side view
        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 1.5, 4); // Side view, slightly elevated
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- LIGHTING ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(-2, 5, 2);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // --- TREADMILL GROUND ---
        const groundGeo = new THREE.PlaneGeometry(10, 20);
        const groundMat = new THREE.MeshStandardMaterial({ 
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Treadmill belt visual (stripes)
        const beltGeo = new THREE.PlaneGeometry(1, 10);
        const beltMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
        const belt = new THREE.Mesh(beltGeo, beltMat);
        belt.rotation.x = -Math.PI / 2;
        belt.position.y = 0.01; // Slightly above ground
        scene.add(belt);

        // --- LOW POLY HUMANOID CREATION ---
        const humanGroup = new THREE.Group();
        scene.add(humanGroup);

        // Materials
        const skinMat = new THREE.MeshStandardMaterial({ color: 0xeebb99 });
        const clothesMat = new THREE.MeshStandardMaterial({ color: 0x2b5797 });

        // Helper to create meshes
        function createCapsule(radius, height, segments, xPos, yPos, zPos, rotationY, isClothes = false) {
            const geo = new THREE.CylinderGeometry(radius, radius, height, 8);
            const mat = isClothes ? clothesMat : skinMat;
            const mesh = new THREE.Mesh(geo, mat);
            mesh.position.set(xPos, yPos, zPos);
            mesh.rotation.y = rotationY;
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            return mesh;
        }

        // Body parts
        const torso = createCapsule(0.25, 0.8, 1, 0, 1.0, 0, 0);
        const head = createCapsule(0.15, 0.3, 1, 0, 1.7, 0, 0);
        const leftArm = createCapsule(0.1, 0.5, 1, -0.35, 1.3, 0, Math.PI / 2);
        const rightArm = createCapsule(0.1, 0.5, 1, 0.35, 1.3, 0, -Math.PI / 2);
        const leftLeg = createCapsule(0.15, 0.6, 1, -0.15, 0.5, 0, Math.PI / 2);
        const rightLeg = createCapsule(0.15, 0.6, 1, 0.15, 0.5, 0, -Math.PI / 2);

        // Hierarchy
        humanGroup.add(head);
        humanGroup.add(torso);

        // Arms attached to torso
        const leftShoulder = new THREE.Group();
        leftShoulder.position.set(-0.35, 1.3, 0);
        torso.add(leftShoulder);
        leftArm.position.y = -0.25; // Offset from shoulder
        leftShoulder.add(leftArm);

        const rightShoulder = new THREE.Group();
        rightShoulder.position.set(0.35, 1.3, 0);
        torso.add(rightShoulder);
        rightArm.position.y = -0.25;
        rightShoulder.add(rightArm);

        // Legs attached to torso
        const leftHip = new THREE.Group();
        leftHip.position.set(-0.15, 0.5, 0);
        torso.add(leftHip);
        leftLeg.position.y = -0.3;
        leftHip.add(leftLeg);

        const rightHip = new THREE.Group();
        rightHip.position.set(0.15, 0.5, 0);
        torso.add(rightHip);
        rightLeg.position.y = -0.3;
        rightHip.add(rightLeg);

        // --- ANIMATION STATE ---

        // Timers
        let startTime = 0;
        let phase = 'stand'; // stand, walk, run
        let cycleStartTime = 0;

        // Animation parameters
        const params = {
            stand: { baseSpeed: 0, lean: 0, armSpeed: 0, legSpeed: 0 },
            walk: { baseSpeed: 0.1, lean: 0.1, armSpeed: 0.08, legSpeed: 0.08 },
            run: { baseSpeed: 0.25, lean: 0.2, armSpeed: 0.15, legSpeed: 0.2 }
        };

        function updateAnimation(deltaTime) {
            const now = performance.now();
            const elapsed = now - cycleStartTime;

            // Phase Management (10s Cycle)
            // 0-2s: Stand
            // 2-5s: Walk
            // 5-8s: Run
            // 8-10s: Stand

            let currentPhase = 'stand';

            if (elapsed < 2000) {
                currentPhase = 'stand';
            } else if (elapsed < 5000) {
                currentPhase = 'walk';
            } else if (elapsed < 8000) {
                currentPhase = 'run';
            } else {
                currentPhase = 'stand';
            }

            // Interpolate between phases
            // We check if the phase has changed to update the base animation offset
            if (phase !== currentPhase) {
                phase = currentPhase;
                // Calculate offset within the current phase duration
                // If entering phase 2 (walk), offset should be 0 relative to start of walk
                // But we need to continue smooth movement.
                // Simple approach: The phase duration is fixed, we just reset the relative time within the phase
                // However, to make it seamless loop, we rely on the sine waves being continuous.
            }

            const p = params[currentPhase];
            const t = (now - cycleStartTime) / 10000; // Normalized 0-1 cycle

            // 1. Body Lean (Running leans forward)
            // Smoothly interpolate lean amount based on phase
            const targetLean = THREE.MathUtils.lerp(0, p.lean, 0.1);
            humanGroup.rotation.z -= (targetLean - humanGroup.rotation.z) * 0.1;

            // 2. Running Bounce (Vertical movement)
            // More bounce in run, less in walk
            const bounceAmp = phase === 'run' ? 0.1 : 0.02;
            const bounceFreq = phase === 'run' ? 10 : 4;
            humanGroup.position.y = Math.sin(now * bounceFreq * 0.001) * bounceAmp;

            // 3. Limb Swinging
            // We use sine waves. 
            // Left leg: sin(t)
            // Right leg: sin(t + PI)
            // To make it look like running, we increase the 'amplitude' of the swing

            const timeFactor = now * 0.001;

            // Legs
            // Base rotation is set during creation (-PI/2 and PI/2). 
            // We add a vertical rotation (pitch) for the swing.

            // Left Leg
            const legSwing = Math.sin(timeFactor * p.legSpeed * 10);
            leftLeg.rotation.x = THREE.MathUtils.lerp(0, legSwing * 0.8, 0.1); // 0.8 is max swing angle

            // Right Leg
            const rightLegSwing = Math.sin(timeFactor * p.legSpeed * 10 + Math.PI);
            rightLeg.rotation.x = THREE.MathUtils.lerp(0, rightLegSwing * 0.8, 0.1);

            // Arms
            // Arms swing opposite to legs
            const armSwing = Math.sin(timeFactor * p.armSpeed * 10);
            leftArm.rotation.x = THREE.MathUtils.lerp(0, armSwing * 0.6, 0.1);
            rightArm.rotation.x = THREE.MathUtils.lerp(0, (armSwing + Math.PI) * 0.6, 0.1);

            // 4. Forward Movement (Simulated by treadmill, but we can fake slight forward bob)
            // Actually, treadmill implies staying in place. 
            // The "Walk" vs "Run" is purely the limb kinematics.
            // We added the bounce and lean.
        }

        // --- RENDER LOOP ---
        function animate() {
            requestAnimationFrame(animate);

            const deltaTime = 1; // Not strictly needed for smooth sine waves, but good for delta-time logic if we added physics

            updateAnimation(performance.now());

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start
        animate();

    </script>
</body>
</html>
```
